class Solution {
    private int[][] cost,memo;
    private int n;
    public int palindromePartition(String s,int k){
        n=s.length();
        cost=new int[n][n];
        for(int length=2;length<=n;length++)for(int left=0;left+length<=n;left++){
            int right=left+length-1;
            cost[left][right]=(length>2?cost[left+1][right-1]:0)+(s.charAt(left)==s.charAt(right)?0:1);
        }
        memo=new int[n][k+1];
        for(int[] row:memo)Arrays.fill(row,-1);
        return dfs(0,k);
    }
    private int dfs(int index,int parts){
        if(parts==1)return cost[index][n-1];
        if(memo[index][parts]>=0)return memo[index][parts];
        int best=1000000;
        for(int end=index;end<=n-parts;end++)best=Math.min(best,cost[index][end]+dfs(end+1,parts-1));
        return memo[index][parts]=best;
    }
}

code.kotlin:
class Solution {
    private lateinit var cost:Array<IntArray>;
    private lateinit var memo:Array<IntArray>;
    private var n=0;
    fun palindromePartition(s:String,k:Int):Int{
        n=s.length;
        cost=Array(n){
            IntArray(n)
        };
        for(length in 2..n)for(left in 0..n-length){
            val right=left+length-1;
            cost[left][right]=(if(length>2)cost[left+1][right-1] else 0)+if(s[left]==s[right])0 else 1
        };
        memo=Array(n){
            IntArray(k+1){
                -1
            }
        };
        return dfs(0,k)
    };
    private fun dfs(index:Int,parts:Int):Int{
        if(parts==1)return cost[index][n-1];
        if(memo[index][parts]>=0)return memo[index][parts];
        var best=1000000;
        for(end in index..n-parts)best=minOf(best,cost[index][end]+dfs(end+1,parts-1));
        memo[index][parts]=best;
        return best
    }
}

